function getSegmentPath(t,a,b){
 // a journey leg = the train's own real route between its two stops (the same path the train view draws)
 const start=t.route.findIndex(p=>p[0]===a),end=t.route.findIndex((p,i)=>i>start&&p[0]===b);   // b after a (ring laps end where they began)
 if(start<0||end<=start)return[];
 const real=getTrainPath(t),ends=routeStopPathEnds.get(t.id)||[];
 return ends[start]>=0&&ends[end]>ends[start]?real.slice(ends[start],ends[end]+1):[];
}
